-- =============================================================================
-- Layered base views for People and Organizations — PART 1 of 2 (metadata + CodeGen)
-- =============================================================================
--
-- Finishes the migration planned in 35bb1fa ("track: move the enriched views to MJ
-- layered base views (MJ#3419)"), which was tracking-only because the MJ feature it
-- needs had not shipped. It has, and MJ core adopted it in its own pilot
-- (MJ migrations/v6/V202608050105).
--
-- WHAT WAS BROKEN. The Person and Organization forms bind a "Primary Address" panel to
-- PrimaryAddressLine1 / City / State / PostalCode / Country / Type. Those columns only
-- ever existed on vwPeopleExtended / vwOrganizationsExtended — hand-written views whose
-- migration now lives in archive/ and which exist in no current database. Every field in
-- the panel named a column that does not exist, so the panel rendered empty.
--
-- WHY TWO MIGRATIONS. The thin wrappers in PART 2 SELECT from the inner views that the
-- CodeGen section BELOW creates. A view cannot be created over a missing object — SQL
-- Server rejects it outright (no deferred name resolution for views) — so the wrappers
-- must land in a separate, later-timestamped file. This is the same split MJ core used,
-- and it is what makes a FRESH INSTALL work: migrations alone produce the finished
-- shape, without depending on the host running CodeGen first.
--
-- WHY THE METADATA IS SQL AND NOT JUST metadata/entities/.entities.json. The Open App
-- installer does not process the metadata/ directory — it relies on migrations for DDL
-- and seed data (see the OpenApp README). The JSON is updated too, for `mj sync push`
-- during development, but a fresh install gets its metadata from right here.
-- =============================================================================

-- Switch both entities from a fully generated base view to a LAYERED one: CodeGen keeps
-- generating everything mechanical under GeneratedBaseViewName, and this app owns BaseView
-- as a thin wrapper. BaseViewGenerated must be 0 for a layered view — a CHECK constraint
-- enforces that the two settings agree.
UPDATE [${mjSchema}].[Entity]
   SET [BaseViewGenerated]      = 0,
       [GeneratedBaseViewName]  = 'vwPeopleGenerated'
 WHERE [ID] = '7A94ADA9-7880-4FAE-97D8-DB0E934C3F5F';  -- MJ_BizApps_Common: People
GO

UPDATE [${mjSchema}].[Entity]
   SET [BaseViewGenerated]      = 0,
       [GeneratedBaseViewName]  = 'vwOrganizationsGenerated'
 WHERE [ID] = 'C70448F9-9792-41D7-A82C-784B66429D54';  -- MJ_BizApps_Common: Organizations
GO


















































