--   EVERYTHING BELOW THIS LINE IS CODEGEN OUTPUT — DO NOT EDIT BY HAND        --
--                                                                             --
--   Generated by `mj codegen` with the metadata above applied, then folded in --
--   here so this migration is self-contained. It creates the inner generated   --
--   views (vwPeopleGenerated / vwOrganizationsGenerated), the regenerated CRUD --
--   procedures for the affected entities, and the EntityField rows for the     --
--   layered columns.                                                           --
--                                                                             --
--   Kept in this file rather than shipped as a side CodeGen_Run_*.sql because  --
--   the schema change and the metadata that describes it are one unit of work: --
--   a deployment applying one without the other would have entity metadata     --
--   that disagrees with its own database.                                      --
--                                                                             --
-- =============================================================================
-- =============================================================================

